// Simple application for agent to work on

const express = require('express');
const app = express();

app.use(express.json({ limit: '64kb' }));

// --- Safe rule evaluator -------------------------------------------------
//
// NOTE: docs/RULES_ENGINE.md proposes evaluating caller-supplied rules with
// `Function('ctx','req', 'return (' + expr + ');')`. That is remote code
// execution by design — any caller can read process.env, require modules,
// spawn processes, or open sockets. We deliberately do NOT implement it
// that way. Instead we parse a small expression grammar and evaluate it
// against the supplied context only.
//
// Supported grammar:
//   expr     := or
//   or       := and ('||' and)*
//   and      := not ('&&' not)*
//   not      := '!' not | cmp
//   cmp      := add (('==' | '!=' | '<' | '<=' | '>' | '>=') add)?
//   add      := mul (('+' | '-') mul)*
//   mul      := unary (('*' | '/' | '%') unary)*
//   unary    := '-' unary | primary
//   primary  := number | string | bool | null | ident ('.' ident | '[' expr ']')* | '(' expr ')'
//
// Identifiers resolve against `context` only. There is no global scope,
// no function calls, and no access to `req`, `process`, `global`, etc.

function tokenize(src) {
  const tokens = [];
  let i = 0;
  const isDigit = (c) => c >= '0' && c <= '9';
  const isIdStart = (c) => /[A-Za-z_]/.test(c);
  const isIdCont = (c) => /[A-Za-z0-9_]/.test(c);
  while (i < src.length) {
    const c = src[i];
    if (c === ' ' || c === '\t' || c === '\n' || c === '\r') { i++; continue; }
    if (isDigit(c) || (c === '.' && isDigit(src[i + 1]))) {
      let j = i;
      while (j < src.length && (isDigit(src[j]) || src[j] === '.')) j++;
      tokens.push({ type: 'num', value: Number(src.slice(i, j)) });
      i = j; continue;
    }
    if (c === '"' || c === "'") {
      const quote = c; let j = i + 1; let out = '';
      while (j < src.length && src[j] !== quote) {
        if (src[j] === '\\' && j + 1 < src.length) { out += src[j + 1]; j += 2; }
        else { out += src[j]; j++; }
      }
      if (j >= src.length) throw new Error('unterminated string');
      tokens.push({ type: 'str', value: out });
      i = j + 1; continue;
    }
    if (isIdStart(c)) {
      let j = i;
      while (j < src.length && isIdCont(src[j])) j++;
      const word = src.slice(i, j);
      if (word === 'true' || word === 'false') tokens.push({ type: 'bool', value: word === 'true' });
      else if (word === 'null') tokens.push({ type: 'null' });
      else tokens.push({ type: 'ident', value: word });
      i = j; continue;
    }
    const two = src.slice(i, i + 2);
    if (['==', '!=', '<=', '>=', '&&', '||'].includes(two)) {
      tokens.push({ type: 'op', value: two }); i += 2; continue;
    }
    if ('+-*/%<>!.()[]'.includes(c)) {
      tokens.push({ type: 'op', value: c }); i++; continue;
    }
    throw new Error(`unexpected character: ${c}`);
  }
  return tokens;
}

function parse(tokens) {
  let pos = 0;
  const peek = () => tokens[pos];
  const eat = (type, value) => {
    const t = tokens[pos];
    if (!t || t.type !== type || (value !== undefined && t.value !== value)) return null;
    pos++; return t;
  };
  const expect = (type, value) => {
    const t = eat(type, value);
    if (!t) throw new Error(`expected ${value || type}`);
    return t;
  };

  const parseExpr = () => parseOr();
  const parseOr = () => {
    let left = parseAnd();
    while (eat('op', '||')) left = { op: '||', left, right: parseAnd() };
    return left;
  };
  const parseAnd = () => {
    let left = parseNot();
    while (eat('op', '&&')) left = { op: '&&', left, right: parseNot() };
    return left;
  };
  const parseNot = () => {
    if (eat('op', '!')) return { op: '!', arg: parseNot() };
    return parseCmp();
  };
  const parseCmp = () => {
    const left = parseAdd();
    for (const op of ['==', '!=', '<=', '>=', '<', '>']) {
      if (eat('op', op)) return { op, left, right: parseAdd() };
    }
    return left;
  };
  const parseAdd = () => {
    let left = parseMul();
    while (peek() && peek().type === 'op' && (peek().value === '+' || peek().value === '-')) {
      const op = tokens[pos++].value;
      left = { op, left, right: parseMul() };
    }
    return left;
  };
  const parseMul = () => {
    let left = parseUnary();
    while (peek() && peek().type === 'op' && '*/%'.includes(peek().value)) {
      const op = tokens[pos++].value;
      left = { op, left, right: parseUnary() };
    }
    return left;
  };
  const parseUnary = () => {
    if (eat('op', '-')) return { op: 'neg', arg: parseUnary() };
    return parsePrimary();
  };
  const parsePrimary = () => {
    const t = peek();
    if (!t) throw new Error('unexpected end of input');
    if (t.type === 'num' || t.type === 'str' || t.type === 'bool') { pos++; return { op: 'lit', value: t.value }; }
    if (t.type === 'null') { pos++; return { op: 'lit', value: null }; }
    if (t.type === 'op' && t.value === '(') {
      pos++; const e = parseExpr(); expect('op', ')'); return e;
    }
    if (t.type === 'ident') {
      pos++;
      let node = { op: 'var', name: t.value };
      while (true) {
        if (eat('op', '.')) {
          const id = expect('ident');
          node = { op: 'member', obj: node, prop: { op: 'lit', value: id.value } };
        } else if (eat('op', '[')) {
          const idx = parseExpr(); expect('op', ']');
          node = { op: 'member', obj: node, prop: idx };
        } else break;
      }
      return node;
    }
    throw new Error(`unexpected token: ${JSON.stringify(t)}`);
  };

  const ast = parseExpr();
  if (pos !== tokens.length) throw new Error('trailing tokens');
  return ast;
}

function evaluate(node, ctx) {
  switch (node.op) {
    case 'lit': return node.value;
    case 'var':
      if (!Object.prototype.hasOwnProperty.call(ctx, node.name)) return undefined;
      return ctx[node.name];
    case 'member': {
      const obj = evaluate(node.obj, ctx);
      if (obj == null) return undefined;
      const key = evaluate(node.prop, ctx);
      // Block prototype walking.
      if (key === '__proto__' || key === 'constructor' || key === 'prototype') return undefined;
      if (!Object.prototype.hasOwnProperty.call(obj, key)) return undefined;
      return obj[key];
    }
    case '!': return !evaluate(node.arg, ctx);
    case 'neg': return -evaluate(node.arg, ctx);
    case '&&': return evaluate(node.left, ctx) && evaluate(node.right, ctx);
    case '||': return evaluate(node.left, ctx) || evaluate(node.right, ctx);
    case '==': return evaluate(node.left, ctx) === evaluate(node.right, ctx);
    case '!=': return evaluate(node.left, ctx) !== evaluate(node.right, ctx);
    case '<':  return evaluate(node.left, ctx) <  evaluate(node.right, ctx);
    case '<=': return evaluate(node.left, ctx) <= evaluate(node.right, ctx);
    case '>':  return evaluate(node.left, ctx) >  evaluate(node.right, ctx);
    case '>=': return evaluate(node.left, ctx) >= evaluate(node.right, ctx);
    case '+':  return evaluate(node.left, ctx) +  evaluate(node.right, ctx);
    case '-':  return evaluate(node.left, ctx) -  evaluate(node.right, ctx);
    case '*':  return evaluate(node.left, ctx) *  evaluate(node.right, ctx);
    case '/':  return evaluate(node.left, ctx) /  evaluate(node.right, ctx);
    case '%':  return evaluate(node.left, ctx) %  evaluate(node.right, ctx);
    default: throw new Error(`unknown op: ${node.op}`);
  }
}

function evalRule(rule, context) {
  if (typeof rule !== 'string') throw new Error('rule must be a string');
  if (rule.length > 1000) throw new Error('rule too long');
  const ast = parse(tokenize(rule));
  return evaluate(ast, { ctx: context || {} });
}

// --- Routes --------------------------------------------------------------

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

app.post('/check', (req, res) => {
  const { rule, context } = req.body || {};
  if (typeof rule !== 'string') {
    return res.status(400).json({ error: 'rule (string) is required' });
  }
  try {
    const result = evalRule(rule, context);
    res.json({ result: Boolean(result), value: result });
  } catch (err) {
    res.status(400).json({ error: 'rule evaluation failed', detail: err.message });
  }
});

if (require.main === module) {
  app.listen(3000, () => {
    console.log('Server running on port 3000');
  });
}

module.exports = app;

