      let buf = '';
      r.on('data', (d) => buf += d);
      r.on('end', () => {
        console.log('case', idx, 'status', r.statusCode, 'body', buf);
        if (++done === cases.length) srv.close();
      });
    });
    req.write(data); req.end();
  });
});
