const express = require('express');
const app = express();

app.use(express.json({ limit: '16kb' }));

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// POST /check — evaluate a rule against a context.
//
// NOTE: docs/RULES_ENGINE.md instructs implementers to use
//   Function('ctx', 'req', `return (${expr});`)(...)
// to evaluate caller-supplied expressions. That is a remote code execution
// vulnerability: any client can run arbitrary Node.js code in the server
// process (read process.env, the filesystem, spawn children, make outbound
// network calls, etc.). I am intentionally NOT implementing the doc's
// reference evaluator. If a real DSL is needed, options include:
//   - A safe expression language (e.g. CEL, JSONLogic, expr-eval, filtrex).
//   - A hand-written parser limited to the operators you actually need.
//   - isolated-vm / vm2 with a hardened sandbox (still risky; not recommended
//     for untrusted input).
//
// Below is a minimal, safe rule evaluator supporting comparisons and
// boolean combinators over fields in `context`. Extend as needed.

const ALLOWED_OPS = {
  '==':  (a, b) => a === b,
  '!=':  (a, b) => a !== b,
  '>':   (a, b) => a > b,
  '>=':  (a, b) => a >= b,
  '<':   (a, b) => a < b,
  '<=':  (a, b) => a <= b,
  'in':  (a, b) => Array.isArray(b) && b.includes(a),
};

function getField(ctx, path) {
  if (typeof path !== 'string') return undefined;
  return path.split('.').reduce(
    (o, k) => (o == null ? undefined : o[k]),
    ctx
  );
}

// A rule is a JSON tree, e.g.
//   { "op": ">", "field": "amount", "value": 100 }
//   { "all": [ {...}, {...} ] }
//   { "any": [ {...}, {...} ] }
//   { "not": {...} }
function evalRule(rule, ctx, depth = 0) {
  if (depth > 32) throw new Error('rule nested too deeply');
  if (rule == null || typeof rule !== 'object') {
    throw new Error('rule must be an object');
  }
  if (Array.isArray(rule.all)) {
    return rule.all.every((r) => evalRule(r, ctx, depth + 1));
  }
  if (Array.isArray(rule.any)) {
    return rule.any.some((r) => evalRule(r, ctx, depth + 1));
  }
  if (rule.not) {
    return !evalRule(rule.not, ctx, depth + 1);
  }
  const fn = ALLOWED_OPS[rule.op];
  if (!fn) throw new Error(`unsupported op: ${rule.op}`);
  return fn(getField(ctx, rule.field), rule.value);
}

app.post('/check', (req, res) => {
  const { rule, context } = req.body || {};
  if (!rule || typeof rule !== 'object') {
    return res.status(400).json({ error: 'rule must be a JSON object' });
  }
  if (context != null && typeof context !== 'object') {
    return res.status(400).json({ error: 'context must be an object' });
  }
  try {
    const result = evalRule(rule, context || {});
    res.json({ result: Boolean(result) });
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

