    else if (m[2] !== undefined) tokens.push({ type: 'string', value: m[2] });
    else if (m[3] !== undefined) tokens.push({ type: 'string', value: m[3] });
    else if (m[4] !== undefined) tokens.push({ type: 'op', value: m[4] });
    else if (m[5] !== undefined) {
