// Standalone test of the rule engine (mirrors logic in app.js)
const COMPARISON_OPS = {
  eq:  (a, b) => a === b,
  ne:  (a, b) => a !== b,
  lt:  (a, b) => a <   b,
  lte: (a, b) => a <=  b,
  gt:  (a, b) => a >   b,
  gte: (a, b) => a >=  b,
  in:  (a, b) => Array.isArray(b) && b.includes(a),
};

function getPath(obj, path) {
  if (typeof path !== 'string' || path.length === 0) return undefined;
  return path.split('.').reduce(
    (acc, key) => (acc != null && Object.prototype.hasOwnProperty.call(acc, key) ? acc[key] : undefined),
    obj,
  );
}

function evalRule(rule, context, depth = 0) {
  if (depth > 32) throw new Error('rule nesting too deep');
  if (rule == null || typeof rule !== 'object') throw new Error('rule must be an object');
  const { op } = rule;
  if (op === 'and' || op === 'or') {
    if (!Array.isArray(rule.rules)) throw new Error(`${op} requires "rules" array`);
    const results = rule.rules.map((r) => evalRule(r, context, depth + 1));
    return op === 'and' ? results.every(Boolean) : results.some(Boolean);
  }
  if (op === 'not') {
    if (!Array.isArray(rule.rules) || rule.rules.length !== 1) throw new Error('not requires a "rules" array of length 1');
    return !evalRule(rule.rules[0], context, depth + 1);
  }
  if (Object.prototype.hasOwnProperty.call(COMPARISON_OPS, op)) {
    return COMPARISON_OPS[op](getPath(context, rule.field), rule.value);
  }
  throw new Error(`unknown op: ${String(op)}`);
}

function check(name, expected, fn) {
  try {
    const got = fn();
    const ok = JSON.stringify(got) === JSON.stringify(expected);
    console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}  =>  ${JSON.stringify(got)}${ok ? '' : `  (expected ${JSON.stringify(expected)})`}`);
  } catch (e) {
    const ok = expected && expected.throws && e.message.includes(expected.throws);
    console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}  =>  threw "${e.message}"`);
  }
}

