// ---------------------------------------------------------------------------
// Safe rule evaluator for POST /check
//
// NOTE: docs/RULES_ENGINE.md proposes evaluating caller-supplied expressions
// with `Function(expr)`. That is a remote code execution vulnerability — any
// client could read files, env vars, or make outbound requests from the
// server process. We deliberately do NOT implement that. Instead we parse a
// restricted predicate grammar that covers the documented use case
// (e.g. `ctx.amount > 100`) without ever invoking the JS evaluator.
//
// Grammar (recursive descent, precedence climbing):
//   expr     := or
//   or       := and ( '||' and )*
//   and      := not ( '&&' not )*
//   not      := '!' not | cmp
//   cmp      := add ( ( '==' | '!=' | '<=' | '>=' | '<' | '>' ) add )?
//   add      := primary
//   primary  := literal | path | '(' expr ')'
//   path     := 'ctx' ( '.' ident )*
//   literal  := number | string | 'true' | 'false' | 'null'
// ---------------------------------------------------------------------------

function tokenize(src) {
  const tokens = [];
  let i = 0;
  while (i < src.length) {
    const c = src[i];
    if (/\s/.test(c)) { i++; continue; }
    if (/[0-9]/.test(c) || (c === '-' && /[0-9]/.test(src[i + 1] || ''))) {
      let j = i + 1;
      while (j < src.length && /[0-9.]/.test(src[j])) j++;
      tokens.push({ type: 'num', value: Number(src.slice(i, j)) });
      i = j; continue;
    }
    if (c === '"' || c === "'") {
      const quote = c;
      let j = i + 1;
      let s = '';
      while (j < src.length && src[j] !== quote) {
        if (src[j] === '\\' && j + 1 < src.length) { s += src[j + 1]; j += 2; }
        else { s += src[j]; j++; }
      }
      if (j >= src.length) throw new Error('Unterminated string literal');
      tokens.push({ type: 'str', value: s });
      i = j + 1; continue;
    }
    if (/[A-Za-z_]/.test(c)) {
      let j = i + 1;
      while (j < src.length && /[A-Za-z0-9_]/.test(src[j])) j++;
      const word = src.slice(i, j);
      if (word === 'true' || word === 'false') tokens.push({ type: 'bool', value: word === 'true' });
      else if (word === 'null') tokens.push({ type: 'null' });
      else tokens.push({ type: 'ident', value: word });
      i = j; continue;
    }
    const two = src.slice(i, i + 2);
    if (['==', '!=', '<=', '>=', '&&', '||'].includes(two)) {
      tokens.push({ type: 'op', value: two }); i += 2; continue;
    }
    if ('<>!().'.includes(c)) {
      tokens.push({ type: 'op', value: c }); i++; continue;
    }
    throw new Error(`Unexpected character: ${c}`);
  }
  return tokens;
}

function parse(tokens) {
  let pos = 0;
  const peek = () => tokens[pos];
  const eat = (type, value) => {
    const t = tokens[pos];
    if (!t || t.type !== type || (value !== undefined && t.value !== value)) {
      throw new Error(`Expected ${type} ${value ?? ''}, got ${JSON.stringify(t)}`);
    }
    pos++; return t;
  };

  function parseExpr() { return parseOr(); }
  function parseOr() {
    let left = parseAnd();
    while (peek() && peek().type === 'op' && peek().value === '||') {
      pos++; left = { kind: 'or', left, right: parseAnd() };
    }
    return left;
  }
  function parseAnd() {
    let left = parseNot();
    while (peek() && peek().type === 'op' && peek().value === '&&') {
      pos++; left = { kind: 'and', left, right: parseNot() };
    }
    return left;
  }
  function parseNot() {
    if (peek() && peek().type === 'op' && peek().value === '!') {
      pos++; return { kind: 'not', expr: parseNot() };
    }
    return parseCmp();
  }
  function parseCmp() {
    const left = parsePrimary();
    const t = peek();
    if (t && t.type === 'op' && ['==', '!=', '<', '<=', '>', '>='].includes(t.value)) {
      pos++; return { kind: 'cmp', op: t.value, left, right: parsePrimary() };
    }
    return left;
  }
  function parsePrimary() {
    const t = peek();
    if (!t) throw new Error('Unexpected end of expression');
    if (t.type === 'op' && t.value === '(') {
      pos++; const e = parseExpr(); eat('op', ')'); return e;
    }
    if (t.type === 'num')  { pos++; return { kind: 'lit', value: t.value }; }
    if (t.type === 'str')  { pos++; return { kind: 'lit', value: t.value }; }
    if (t.type === 'bool') { pos++; return { kind: 'lit', value: t.value }; }
    if (t.type === 'null') { pos++; return { kind: 'lit', value: null }; }
    if (t.type === 'ident') {
      if (t.value !== 'ctx') {
        throw new Error(`Only 'ctx' identifier is allowed, got '${t.value}'`);
      }
      pos++;
      const path = [];
      while (peek() && peek().type === 'op' && peek().value === '.') {
        pos++;
        const id = eat('ident');
        path.push(id.value);
      }
      return { kind: 'path', path };
    }
    throw new Error(`Unexpected token: ${JSON.stringify(t)}`);
  }

  const ast = parseExpr();
  if (pos !== tokens.length) throw new Error('Trailing tokens after expression');
  return ast;
}

function evalAst(ast, ctx) {
  switch (ast.kind) {
    case 'lit': return ast.value;
    case 'path': {
      let cur = ctx;
      for (const seg of ast.path) {
        if (cur == null) return undefined;
        // own-property access only — no prototype walking
        cur = Object.prototype.hasOwnProperty.call(cur, seg) ? cur[seg] : undefined;
      }
      return cur;
    }
    case 'not': return !evalAst(ast.expr, ctx);
    case 'and': return evalAst(ast.left, ctx) && evalAst(ast.right, ctx);
    case 'or':  return evalAst(ast.left, ctx) || evalAst(ast.right, ctx);
    case 'cmp': {
      const l = evalAst(ast.left, ctx);
      const r = evalAst(ast.right, ctx);
      switch (ast.op) {
        case '==': return l === r;
        case '!=': return l !== r;
        case '<':  return l <  r;
        case '<=': return l <= r;
        case '>':  return l >  r;
        case '>=': return l >= r;
      }
    }
  }
  throw new Error(`Unknown node: ${ast.kind}`);
}

function evalRule(rule, context) {
  if (typeof rule !== 'string') throw new Error('rule must be a string');
  if (rule.length > 1000) throw new Error('rule too long');
  const ast = parse(tokenize(rule));
  return Boolean(evalAst(ast, context ?? {}));
}

app.post('/check', (req, res) => {
  const { rule, context } = req.body || {};
  if (typeof rule !== 'string') {
    return res.status(400).json({ error: "Missing or invalid 'rule' (must be a string)" });
  }
  try {
    const result = evalRule(rule, context);
    res.json({ result });
  } catch (err) {
    res.status(400).json({ error: `Rule evaluation failed: ${err.message}` });
  }
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

