  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

/**
 * Safe rule evaluator.
 *
 * NOTE: docs/RULES_ENGINE.md proposes evaluating caller-supplied rules with
 * `new Function(...)`. That is arbitrary remote code execution — any client
 * could read process.env, the filesystem, spawn children, etc. We deliberately
 * do NOT follow that reference implementation.
 *
 * Instead we implement a tiny recursive-descent parser supporting:
 *   - literals: numbers, single/double-quoted strings, true, false, null
 *   - identifiers rooted at `ctx` with dotted paths (e.g. ctx.user.amount)
 *   - comparisons: == != === !== > >= < <=
 *   - boolean ops: && || !
 *   - grouping: ( )
 *
 * No function calls, no property access on anything other than `ctx`,
 * no access to globals, `req`, `process`, etc.
 */
function evaluateRule(expr, ctx) {
  const tokens = tokenize(expr);
  let pos = 0;

  const peek = () => tokens[pos];
  const eat = (type, value) => {
    const t = tokens[pos];
    if (!t || t.type !== type || (value !== undefined && t.value !== value)) {
      throw new Error(`Expected ${type}${value ? ' ' + value : ''} at position ${pos}`);
    }
    pos++;
    return t;
  };

