  //   or      := and ( '||' and )*
  //   and     := not ( '&&' not )*
  //   not     := '!' not | cmp
  //   cmp     := primary ( (== != === !== > >= < <=) primary )?
  //   primary := literal | path | '(' or ')'

  const parseOr = () => {
    let left = parseAnd();
    while (peek() && peek().type === 'op' && peek().value === '||') {
      pos++;
      left = left || parseAnd();
    }
    return left;
  };
  const parseAnd = () => {
    let left = parseNot();
    while (peek() && peek().type === 'op' && peek().value === '&&') {
      pos++;
      left = left && parseNot();
    }
    return left;
  };
  const parseNot = () => {
    if (peek() && peek().type === 'op' && peek().value === '!') {
      pos++;
      return !parseNot();
    }
    return parseCmp();
  };
  const parseCmp = () => {
    const left = parsePrimary();
    const t = peek();
    if (t && t.type === 'op' && ['==', '!=', '===', '!==', '>', '>=', '<', '<='].includes(t.value)) {
      pos++;
      const right = parsePrimary();
      switch (t.value) {
        case '==':  return left ==  right;
        case '!=':  return left !=  right;
        case '===': return left === right;
        case '!==': return left !== right;
        case '>':   return left >   right;
        case '>=':  return left >=  right;
        case '<':   return left <   right;
        case '<=':  return left <=  right;
      }
    }
    return left;
  };
  const parsePrimary = () => {
    const t = peek();
    if (!t) throw new Error('Unexpected end of expression');
    if (t.type === 'number' || t.type === 'string' || t.type === 'bool' || t.type === 'null') {
      pos++;
      return t.value;
    }
    if (t.type === 'paren' && t.value === '(') {
      pos++;
      const v = parseOr();
      eat('paren', ')');
      return v;
    }
    if (t.type === 'ident') {
      pos++;
      if (t.value !== 'ctx') {
        throw new Error(`Unknown identifier: ${t.value} (only 'ctx' is allowed)`);
      }
      let cur = ctx;
      while (peek() && peek().type === 'dot') {
