      }
      return cur;
    }
    throw new Error(`Unexpected token: ${JSON.stringify(t)}`);
  };

  const result = parseOr();
  if (pos !== tokens.length) throw new Error(`Unexpected trailing input at position ${pos}`);
  return result;
}

function tokenize(src) {
  const tokens = [];
  let i = 0;
  const isIdStart = c => /[A-Za-z_$]/.test(c);
  const isIdCont  = c => /[A-Za-z0-9_$]/.test(c);
  while (i < src.length) {
    const c = src[i];
    if (/\s/.test(c)) { i++; continue; }
    if (c === '(' || c === ')') { tokens.push({ type: 'paren', value: c }); i++; continue; }
    if (c === '.') { tokens.push({ type: 'dot' }); i++; continue; }
    // multi-char operators
    const three = src.slice(i, i + 3);
    if (three === '===' || three === '!==') { tokens.push({ type: 'op', value: three }); i += 3; continue; }
    const two = src.slice(i, i + 2);
    if (['==','!=','>=','<=','&&','||'].includes(two)) { tokens.push({ type: 'op', value: two }); i += 2; continue; }
    if (c === '>' || c === '<' || c === '!') { tokens.push({ type: 'op', value: c }); i++; continue; }
    if (c === '"' || c === "'") {
      const quote = c; i++;
      let s = '';
      while (i < src.length && src[i] !== quote) {
        if (src[i] === '\\' && i + 1 < src.length) { s += src[i + 1]; i += 2; }
        else { s += src[i++]; }
      }
      if (src[i] !== quote) throw new Error('Unterminated string');
      i++;
      tokens.push({ type: 'string', value: s });
      continue;
    }
    if (/[0-9]/.test(c)) {
      let n = '';
      while (i < src.length && /[0-9.]/.test(src[i])) n += src[i++];
      tokens.push({ type: 'number', value: Number(n) });
      continue;
    }
    if (isIdStart(c)) {
      let id = '';
      while (i < src.length && isIdCont(src[i])) id += src[i++];
      if (id === 'true')  tokens.push({ type: 'bool', value: true });
      else if (id === 'false') tokens.push({ type: 'bool', value: false });
      else if (id === 'null')  tokens.push({ type: 'null', value: null });
      else tokens.push({ type: 'ident', value: id });
      continue;
    }
    throw new Error(`Unexpected character '${c}' at position ${i}`);
  }
  return tokens;
}

app.post('/check', (req, res) => {
  const { rule, context } = req.body || {};
  if (typeof rule !== 'string') {
    return res.status(400).json({ error: 'rule must be a string' });
