    return res.json({ result });
  } catch (err) {
    return res.status(400).json({ error: 'invalid rule', detail: err.message });
  }
});

if (require.main === module) {
  app.listen(3000, () => {
    console.log('Server running on port 3000');
  });
}

module.exports = app;
module.exports.evaluateRule = evaluateRule;

